package agentadapters

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

func TestDockerfilesUseEmbeddedACPAdapters(t *testing.T) {
	t.Parallel()

	for _, name := range []string{"Dockerfile", "Dockerfile.release"} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			raw, err := os.ReadFile(filepath.Join("..", "..", name))
			if err != nil {
				t.Fatalf("read %s: %v", name, err)
			}
			text := string(raw)
			for _, required := range []string{
				"@openai/codex@${OPENAI_CODEX_VERSION}",
				"@anthropic-ai/claude-code@${CLAUDE_CODE_VERSION}",
			} {
				if !strings.Contains(text, required) {
					t.Fatalf("%s is missing provider CLI contract %q", name, required)
				}
			}
			for _, forbidden := range []string{
				"adapter-downloader",
				"ACP_ADAPTER_VERSION",
				"/usr/local/bin/codex-acp-adapter",
				"/usr/local/bin/claude-code-acp-adapter",
				"@hecatehq/codex-acp-adapter",
				"@hecatehq/claude-code-acp-adapter",
				"@zed-industries/codex-acp",
				"@agentclientprotocol/claude-agent-acp",
			} {
				if strings.Contains(text, forbidden) {
					t.Fatalf("%s contains standalone ACP adapter packaging %q", name, forbidden)
				}
			}
		})
	}
}

func TestDockerfilesPinAndVerifySameCursorAgentArtifacts(t *testing.T) {
	t.Parallel()

	dev := readDockerfile(t, "Dockerfile")
	release := readDockerfile(t, "Dockerfile.release")
	versionPattern := regexp.MustCompile(`^\d{4}\.\d{2}\.\d{2}-[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`)
	checksumPattern := regexp.MustCompile(`^[a-f0-9]{64}$`)

	for _, arg := range []string{
		"CURSOR_AGENT_VERSION",
		"CURSOR_AGENT_LINUX_X64_SHA256",
		"CURSOR_AGENT_LINUX_ARM64_SHA256",
	} {
		devValue := dockerfileArgValue(dev, arg)
		releaseValue := dockerfileArgValue(release, arg)
		if devValue == "" || releaseValue == "" {
			t.Fatalf("%s = dev:%q release:%q, want both Dockerfiles pinned", arg, devValue, releaseValue)
		}
		if devValue != releaseValue {
			t.Fatalf("%s drifted: Dockerfile=%s Dockerfile.release=%s", arg, devValue, releaseValue)
		}
		if arg == "CURSOR_AGENT_VERSION" && !versionPattern.MatchString(devValue) {
			t.Fatalf("%s = %q, want a versioned Cursor Agent artifact", arg, devValue)
		}
		if strings.HasSuffix(arg, "SHA256") && !checksumPattern.MatchString(devValue) {
			t.Fatalf("%s = %q, want a lowercase SHA-256", arg, devValue)
		}
	}

	for _, dockerfile := range []struct {
		name string
		text string
	}{
		{name: "Dockerfile", text: dev},
		{name: "Dockerfile.release", text: release},
	} {
		for _, required := range []string{
			`amd64) cursor_arch=x64`,
			`arm64) cursor_arch=arm64`,
			`https://downloads.cursor.com/lab/${CURSOR_AGENT_VERSION}/linux/${cursor_arch}/agent-cli-package.tar.gz`,
			`printf '%s  %s\n' "${cursor_sha256}" "${cursor_archive}" | sha256sum -c -`,
			`tar --no-same-owner --no-same-permissions --strip-components=1 -xzf "${cursor_archive}"`,
			`test -x "${cursor_dir}/cursor-agent"`,
			`test -x "${cursor_dir}/node"`,
		} {
			if !strings.Contains(dockerfile.text, required) {
				t.Errorf("%s is missing Cursor Agent artifact contract %q", dockerfile.name, required)
			}
		}
		for _, forbidden := range []string{
			"https://cursor.com/install",
			"CURSOR_INSTALL_SHA256",
			"CURSOR_INSTALL_URL",
			"cursor-install.sh",
		} {
			if strings.Contains(dockerfile.text, forbidden) {
				t.Errorf("%s still uses mutable Cursor installer contract %q", dockerfile.name, forbidden)
			}
		}
		checksumAt := strings.Index(dockerfile.text, "sha256sum -c -")
		extractAt := strings.Index(dockerfile.text, "tar --no-same-owner")
		if checksumAt == -1 || extractAt == -1 || checksumAt > extractAt {
			t.Errorf("%s must verify the Cursor Agent archive before extracting it", dockerfile.name)
		}
	}
}

func TestCursorAgentUpdateWorkflowIsReviewOnly(t *testing.T) {
	t.Parallel()

	workflow := readRepoFile(t, ".github/workflows/cursor-agent-update.yml")
	for _, required := range []string{
		"schedule:",
		"workflow_dispatch:",
		"contents: read",
		"github.ref == 'refs/heads/master'",
		"actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1",
		"actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e",
		"actions/create-github-app-token@bcd2ba49218906704ab6c1aa796996da409d3eb1",
		"persist-credentials: false",
		"permission-contents: write",
		"permission-pull-requests: write",
		"permission-administration: read",
		"go run ./scripts/cursoragentupdate",
		"--existing-proposal-root",
		"automation/cursor-agent-update",
		"git ls-remote --exit-code --heads",
		"git merge-base --is-ancestor",
		"Existing automation proposal contains unrelated tracked changes",
		"EXISTING_PROPOSAL_PR",
		"cursor-agent-open-prs.json",
		`head=${GITHUB_REPOSITORY_OWNER}:${UPDATE_BRANCH}`,
		"refusing ambiguous publication",
		"refs/remotes/origin/${UPDATE_BRANCH}^",
		"git diff --quiet \"refs/remotes/origin/${UPDATE_BRANCH}\" --",
		"publish=false",
		"repos/${GITHUB_REPOSITORY}/branches/master/protection",
		`.allow_deletions.enabled == false`,
		`.allow_force_pushes.enabled == false`,
		`.enforce_admins.enabled == true`,
		`.restrictions.apps == []`,
		`.permissions.administration == "read"`,
		`(.required_pull_request_reviews | type) == "object"`,
		`any(.required_status_checks.contexts[]?; . == "Required checks")`,
		`.required_status_checks.strict == true`,
		"--force-with-lease",
		"gh pr create",
	} {
		if !strings.Contains(workflow, required) {
			t.Errorf("cursor-agent-update.yml is missing automation contract %q", required)
		}
	}
	for _, forbidden := range []string{
		"pull_request_target:",
		"actions: write",
		"permission-administration: write",
		"gh pr merge",
		"--auto",
		"mapfile -t open_pr_numbers < <(gh pr list",
		"gh pr list",
		`git diff --name-only "${branch_parent}" "${branch_ref}" |`,
	} {
		if strings.Contains(workflow, forbidden) {
			t.Errorf("cursor-agent-update.yml contains unsafe automation %q", forbidden)
		}
	}
	validationAt := strings.Index(workflow, "go run ./scripts/cursoragentupdate")
	readTokenAt := strings.Index(workflow, "name: Create protection reader token")
	protectionAt := strings.Index(workflow, "name: Require protected default branch")
	writeTokenAt := strings.Index(workflow, "name: Create updater App token")
	if validationAt == -1 || readTokenAt == -1 || protectionAt == -1 || writeTokenAt == -1 ||
		readTokenAt < validationAt || protectionAt < readTokenAt || writeTokenAt < protectionAt {
		t.Error("cursor-agent-update.yml must mint its write token only after artifact and branch-rule validation")
	}
}

func TestMainWorkflowExposesStableRequiredCheck(t *testing.T) {
	t.Parallel()

	workflow := readRepoFile(t, ".github/workflows/test.yml")
	for _, required := range []string{
		"required:",
		"name: Required checks",
		"if: always()",
		"NEEDS_JSON: ${{ toJSON(needs) }}",
		`all(.[]; .result == "success" or .result == "skipped")`,
	} {
		if !strings.Contains(workflow, required) {
			t.Errorf("test.yml is missing stable required-check contract %q", required)
		}
	}
}

func readDockerfile(t testing.TB, name string) string {
	t.Helper()
	return readRepoFile(t, name)
}

func readRepoFile(t testing.TB, name string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", name))
	if err != nil {
		t.Fatalf("read %s: %v", name, err)
	}
	return string(raw)
}

func dockerfileArgValue(text string, name string) string {
	prefix := "ARG " + name + "="
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, prefix) {
			return strings.TrimSpace(strings.TrimPrefix(line, prefix))
		}
	}
	return ""
}

//go:build e2e

package e2e

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/hecatehq/hecate/internal/remoteruntime"
)

func TestBrowserSetupEnvironmentIsPassiveE2E(t *testing.T) {
	executable, marker := buildE2EBrowserSentinel(t)
	baseURL := browserSetupServer(t,
		"HECATE_TASK_BROWSER_EXECUTABLE="+executable,
		"HECATE_E2E_BROWSER_MARKER="+marker,
	)
	for range 2 {
		settings := readE2EBrowserSettings(t, baseURL, http.MethodGet, "")
		if settings.Data.Source != "environment" || settings.Data.Selected == nil || settings.Data.Selected.Path != executable || settings.Data.Selected.ID == "" {
			t.Fatalf("environment browser selection = %+v", settings.Data)
		}
		assertE2EBrowserSetupState(t, settings.Data.Readiness, "configured", true)
		assertE2EBrowserReadiness(t, baseURL, nil, "configured", true, executable)
	}
	for _, method := range []string{http.MethodPut, http.MethodDelete} {
		body := browserSetupRequest(t, baseURL+"/hecate/v1/settings/browser", method, `{"candidate_id":"not-a-discovered-candidate"}`, nil, http.StatusConflict)
		var response struct {
			Error struct {
				Type string `json:"type"`
			} `json:"error"`
		}
		if err := json.Unmarshal(body, &response); err != nil {
			t.Fatal(err)
		}
		if response.Error.Type != "browser.environment_managed" {
			t.Fatalf("%s conflict type = %q", method, response.Error.Type)
		}
	}
	// Losing the explicitly configured installation must not select a discovered
	// browser instead. The sentinel belongs exclusively to this temporary test.
	if err := os.Remove(executable); err != nil {
		t.Fatal(err)
	}
	settings := readE2EBrowserSettings(t, baseURL, http.MethodGet, "")
	if settings.Data.Source != "environment" || settings.Data.Selected == nil || settings.Data.Selected.Path != executable {
		t.Fatalf("missing environment installation fell back: %+v", settings.Data)
	}
	assertE2EBrowserSetupState(t, settings.Data.Readiness, "unavailable", false)
	assertE2EBrowserReadiness(t, baseURL, nil, "unavailable", false, executable)
	if _, err := os.Stat(marker); !os.IsNotExist(err) {
		t.Fatalf("browser setup executed the sentinel: %v", err)
	}
}

func TestBrowserSetupInstalledSelectionE2E(t *testing.T) {
	baseURL := browserSetupServer(t)
	settings := readE2EBrowserSettings(t, baseURL, http.MethodGet, "")
	if settings.Data.Source != "none" || settings.Data.Selected != nil {
		t.Fatalf("discovery automatically selected a browser: %+v", settings.Data)
	}
	assertE2EBrowserSetupState(t, settings.Data.Readiness, "not_configured", false)
	assertE2EBrowserReadiness(t, baseURL, nil, "not_configured", false)
	t.Run("enable and disable discovered installation", func(t *testing.T) {
		if len(settings.Data.Candidates) == 0 {
			t.Skip("no supported installed browser; passive discovery assertions still ran")
		}
		candidate := settings.Data.Candidates[0]
		if candidate.ID == "" || candidate.Name == "" || candidate.Path == "" {
			t.Fatalf("incomplete discovered candidate: %+v", candidate)
		}
		enabled := readE2EBrowserSettings(t, baseURL, http.MethodPut, fmt.Sprintf(`{"candidate_id":%q}`, candidate.ID))
		if enabled.Data.Source != "settings" || enabled.Data.Selected == nil || *enabled.Data.Selected != candidate {
			t.Fatalf("enabled browser = %+v, want %+v", enabled.Data, candidate)
		}
		assertE2EBrowserSetupState(t, enabled.Data.Readiness, "configured", true)
		readback := readE2EBrowserSettings(t, baseURL, http.MethodGet, "")
		if readback.Data.Selected == nil || *readback.Data.Selected != candidate || readback.Data.Source != "settings" {
			t.Fatalf("saved browser readback = %+v", readback.Data)
		}
		assertE2EBrowserReadiness(t, baseURL, nil, "configured", true, candidate.Path)
		disabled := readE2EBrowserSettings(t, baseURL, http.MethodDelete, "")
		if disabled.Data.Source != "none" || disabled.Data.Selected != nil {
			t.Fatalf("disabled browser selection = %+v", disabled.Data)
		}
		assertE2EBrowserSetupState(t, disabled.Data.Readiness, "not_configured", false)
		assertE2EBrowserReadiness(t, baseURL, nil, "not_configured", false, candidate.Path)
	})
}

func TestBrowserSetupRemoteRuntimeBoundaryE2E(t *testing.T) {
	const secret = "browser-setup-remote-secret-for-tests"
	baseURL := browserSetupServer(t,
		"HECATE_REMOTE_RUNTIME_MODE=1",
		"HECATE_REMOTE_RUNTIME_SECRET="+secret,
	)
	headers := map[string]string{
		remoteruntime.HeaderRuntimeSecret: secret,
		remoteruntime.HeaderActorID:       "browser-setup-actor",
		remoteruntime.HeaderOrgID:         "browser-setup-org",
		remoteruntime.HeaderRuntimeID:     "browser-setup-runtime",
	}
	for _, method := range []string{http.MethodGet, http.MethodPut, http.MethodDelete} {
		body := browserSetupRequest(t, baseURL+"/hecate/v1/settings/browser", method, `{"candidate_id":"unavailable"}`, headers, http.StatusForbidden)
		if strings.Contains(string(body), `"candidates"`) || strings.Contains(string(body), `"selected"`) || strings.Contains(string(body), `"path"`) {
			t.Fatalf("remote setup exposed installation details: %s", body)
		}
	}
	assertE2EBrowserReadiness(t, baseURL, headers, "local_only", false)
}

type e2eBrowserSetupReadiness struct {
	Available bool   `json:"available"`
	Status    string `json:"status"`
}

type e2eBrowserSetupCandidate struct {
	ID   string `json:"id"`
	Name string `json:"name"`
	Path string `json:"path"`
}

type e2eBrowserSetupResponse struct {
	Object string `json:"object"`
	Data   struct {
		Readiness  e2eBrowserSetupReadiness   `json:"readiness"`
		Source     string                     `json:"source"`
		Selected   *e2eBrowserSetupCandidate  `json:"selected"`
		Candidates []e2eBrowserSetupCandidate `json:"candidates"`
		Backend    string                     `json:"backend"`
	} `json:"data"`
}

func browserSetupServer(t *testing.T, extraEnv ...string) string {
	t.Helper()
	env := []string{
		"HECATE_BACKEND=sqlite", "HECATE_TASK_BROWSER_EXECUTABLE=", "HECATE_TASK_BROWSER_TIMEOUT=20s",
		"HECATE_REMOTE_RUNTIME_MODE=0", "HECATE_REMOTE_RUNTIME_SECRET=",
		"HECATE_RUNTIME_TOKEN=", "HECATE_INFERENCE_TOKEN=",
		"HECATE_OPERATOR_TERMINALS=0", "HECATE_AGENT_ADAPTER_TERMINALS=0",
	}
	return gatewayServer(t, append(env, extraEnv...)...)
}

func readE2EBrowserSettings(t *testing.T, baseURL, method, requestBody string) e2eBrowserSetupResponse {
	t.Helper()
	body := browserSetupRequest(t, baseURL+"/hecate/v1/settings/browser", method, requestBody, nil, http.StatusOK)
	var settings e2eBrowserSetupResponse
	if err := json.Unmarshal(body, &settings); err != nil {
		t.Fatal(err)
	}
	if settings.Object != "browser_settings" || settings.Data.Backend != "sqlite" || settings.Data.Candidates == nil {
		t.Fatalf("browser settings envelope = %s", body)
	}
	return settings
}

func browserSetupRequest(t *testing.T, url, method, body string, headers map[string]string, wantStatus int) []byte {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, method, url, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	if body != "" {
		request.Header.Set("Content-Type", "application/json")
	}
	for name, value := range headers {
		request.Header.Set(name, value)
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	result := readBody(t, response)
	if response.StatusCode != wantStatus {
		t.Fatalf("%s %s status=%d, want %d: %s", method, url, response.StatusCode, wantStatus, result)
	}
	if strings.HasSuffix(url, "/settings/browser") && wantStatus != http.StatusForbidden && response.Header.Get("Cache-Control") != "private, no-store" {
		t.Fatalf("browser setup cache policy = %q", response.Header.Get("Cache-Control"))
	}
	return []byte(result)
}

func assertE2EBrowserSetupState(t *testing.T, readiness e2eBrowserSetupReadiness, status string, available bool) {
	t.Helper()
	if readiness.Status != status || readiness.Available != available {
		t.Fatalf("browser readiness = %+v, want status=%s available=%t", readiness, status, available)
	}
}

func assertE2EBrowserReadiness(t *testing.T, baseURL string, headers map[string]string, status string, available bool, privatePaths ...string) {
	t.Helper()
	body := browserSetupRequest(t, baseURL+"/hecate/v1/settings", http.MethodGet, "", headers, http.StatusOK)
	var settings struct {
		Object string `json:"object"`
		Data   struct {
			Readiness json.RawMessage `json:"browser_evidence"`
		} `json:"data"`
	}
	if err := json.Unmarshal(body, &settings); err != nil {
		t.Fatal(err)
	}
	if settings.Object != "settings" || len(settings.Data.Readiness) == 0 {
		t.Fatalf("general settings envelope = %s", body)
	}
	var readiness e2eBrowserSetupReadiness
	if err := json.Unmarshal(settings.Data.Readiness, &readiness); err != nil {
		t.Fatal(err)
	}
	assertE2EBrowserSetupState(t, readiness, status, available)
	var fields map[string]any
	if err := json.Unmarshal(settings.Data.Readiness, &fields); err != nil {
		t.Fatal(err)
	}
	for name, value := range fields {
		switch name {
		case "available", "status", "message", "operator_action":
		default:
			t.Fatalf("shared browser readiness exposed unexpected field %q", name)
		}
		if text, ok := value.(string); ok {
			for _, path := range privatePaths {
				if path != "" && strings.Contains(text, path) {
					t.Fatalf("shared browser readiness exposed installation path in %s", name)
				}
			}
		}
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"reflect"
	"testing"

	"github.com/hecatehq/cairnline"
	"github.com/hecatehq/hecate/internal/config"
	"github.com/hecatehq/hecate/internal/memory"
	"github.com/hecatehq/hecate/internal/projects"
	"github.com/hecatehq/hecate/internal/projectskills"
	"github.com/hecatehq/hecate/internal/projectwork"
)

func TestProjectSetupReadiness_ReadOnlyPristineProject(t *testing.T) {
	t.Parallel()
	handler, server := newProjectWorkTestServer()
	if _, err := handler.projects.Create(t.Context(), projects.Project{
		ID:   "proj_setup",
		Name: "Setup",
	}); err != nil {
		t.Fatalf("Create project: %v", err)
	}

	beforeWork, err := handler.projectWork.ListWorkItems(t.Context(), "proj_setup")
	if err != nil {
		t.Fatalf("ListWorkItems before: %v", err)
	}
	beforeRoles, err := handler.projectWork.ListRoles(t.Context(), "proj_setup")
	if err != nil {
		t.Fatalf("ListRoles before: %v", err)
	}

	rec := httptest.NewRecorder()
	server.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/hecate/v1/projects/proj_setup/setup-readiness", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("setup readiness status = %d body=%s, want 200", rec.Code, rec.Body.String())
	}
	var response ProjectSetupReadinessEnvelope
	if err := json.Unmarshal(rec.Body.Bytes(), &response); err != nil {
		t.Fatalf("decode setup readiness: %v", err)
	}
	if response.Object != "project_setup_readiness" || response.Data.ProjectID != "proj_setup" {
		t.Fatalf("setup readiness envelope = %+v, want project_setup_readiness for project", response)
	}
	if response.Data.ReadBackend != "hecate" {
		t.Fatalf("setup readiness read_backend = %q, want hecate", response.Data.ReadBackend)
	}
	if !response.Data.ShowOnboarding || response.Data.SetupStarted || response.Data.FirstWorkReady {
		t.Fatalf("setup readiness flags = %+v, want onboarding for pristine project", response.Data)
	}
	if response.Data.Summary.WorkItemCount != 0 || response.Data.Summary.RoleCount != 0 || !response.Data.Summary.MissingDefaults {
		t.Fatalf("setup readiness summary = %+v, want empty project with missing defaults", response.Data.Summary)
	}
	if response.Data.PrimaryAction.Type != projectSetupReadinessActionCreateWorkItem || response.Data.PrimaryAction.Label != "Create first work" {
		t.Fatalf("primary action = %+v, want rootless first-work action", response.Data.PrimaryAction)
	}
	purpose := findProjectSetupReadinessCheckForTest(t, response.Data.Checks, "purpose")
	if purpose.Status != projectSetupReadinessStatusTodo || purpose.Action == nil || purpose.Action.Type != projectSetupReadinessActionProjectSettings {
		t.Fatalf("purpose check = %+v, want settings todo", purpose)
	}
	workspace := findProjectSetupReadinessCheckForTest(t, response.Data.Checks, "workspace_source")
	if workspace.Status != projectSetupReadinessStatusOptional || !workspace.Optional || workspace.Action != nil {
		t.Fatalf("workspace check = %+v, want optional without action", workspace)
	}
	sources := findProjectSetupReadinessCheckForTest(t, response.Data.Checks, "sources_memory")
	if sources.Status != projectSetupReadinessStatusTodo || sources.Action == nil || sources.Action.Type != projectSetupReadinessActionBootstrap {
		t.Fatalf("sources check = %+v, want bootstrap todo", sources)
	}
	firstWork := findProjectSetupReadinessCheckForTest(t, response.Data.Checks, "first_work_item")
	if firstWork.Status != projectSetupReadinessStatusTodo || firstWork.Action == nil || firstWork.Action.Type != projectSetupReadinessActionCreateWorkItem {
		t.Fatalf("first work check = %+v, want create-work todo", firstWork)
	}

	afterWork, err := handler.projectWork.ListWorkItems(t.Context(), "proj_setup")
	if err != nil {
		t.Fatalf("ListWorkItems after: %v", err)
	}
	afterRoles, err := handler.projectWork.ListRoles(t.Context(), "proj_setup")
	if err != nil {
		t.Fatalf("ListRoles after: %v", err)
	}
	if len(beforeWork) != len(afterWork) || len(beforeRoles) != len(afterRoles) {
		t.Fatalf("setup readiness mutated project state: work %d->%d roles %d->%d", len(beforeWork), len(afterWork), len(beforeRoles), len(afterRoles))
	}
}

func TestProjectSetupReadiness_RootedPristineProjectOffersSetup(t *testing.T) {
	t.Parallel()
	handler, server := newProjectWorkTestServer()
	if _, err := handler.projects.Create(t.Context(), projects.Project{
		ID:    "proj_rooted_setup",
		Name:  "Rooted setup",
		Roots: []projects.Root{{ID: "root_setup", Path: t.TempDir(), Kind: "git", Active: true}},
	}); err != nil {
		t.Fatalf("Create project: %v", err)
	}

	rec := httptest.NewRecorder()
